import { configure } from '@storybook/react';

// automatically import all files ending in *.stories.js
const req = require.context('../stories', true, /.stories.js$/);
function loadStories() {
  req.keys().forEach(filename => req(filename));
}

configure(loadStories, module);

import React from 'react';
import PropTypes from 'prop-types';
import styles from './index.scss';

class Navbar extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            mobileOpened: false,
            notFirstAnimation: false,
        };
        this.toggleMenu = this.toggleMenu.bind(this);
    }
    toggleMenu() {
        this.setState({
            mobileOpened: !this.state.mobileOpened,
            notFirstAnimation: true,
        });
    }
    render() {
        return (
            <React.Fragment>
                <nav
                    className={styles.Navbar}
                    {...this.props}
                >
                    <div
                        className={styles.TitleArea}
                    >
                        {this.props.title}
                    </div>
                    <div
                        className={styles.DesktopNav}
                    >
                        <ul>
                            {this.props.tabs.map((tab, key) => (
                                <li
                                    key={key}
                                    className={tab.active ? styles.ActiveLink : ''}
                                >
                                    <a
                                        href={tab.href}
                                    >
                                        {tab.title}
                                    </a>
                                </li>
                            ))}
                        </ul>
                    </div>
                    <div
                        className={styles.MenuButton}
                    >
                        <button
                            onClick={this.toggleMenu}
                        >
                            Menu
                        </button>
                    </div>
                </nav>
                <div
                    className={`${styles.Popover} ${
                        this.state.mobileOpened
                            ? styles.PopOpen
                            : styles.PopClosed
                    }`}
                    {...this.props}
                    style={!this.state.notFirstAnimation ? { display: 'none' } : { ...this.props.style }}
                >
                    <div className={styles.MobileNav}>
                        <ul>
                            {this.props.tabs.map((tab, key) => (
                                <li
                                    key={key}
                                    className={tab.active ? styles.ActiveLink : ''}
                                >
                                    <a
                                        href={tab.href}
                                    >
                                        {tab.title}
                                    </a>
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </React.Fragment>
        );
    }
}

Navbar.defaultProps = {
    title: <h1>Default Title</h1>,
    tabs: [],
};

Navbar.propTypes = {
    title: PropTypes.node,
    tabs: PropTypes.arrayOf(PropTypes.shape({
        href: PropTypes.string,
        title: PropTypes.string,
        active: PropTypes.bool,
    })),
};

export default Navbar;

import React from 'react';
import PropTypes from 'prop-types';
import styles from './index.scss';

const Jumbotron = ({
    children,
    imgSrc,
    imgAlt,
    imgRadius,
    imgStyle,
    ...props
}) => (
    <div
        className={styles.Jumbotron}
        {...props}
    >
        <div
            className={styles.JumbotronInner}
        >
            <img
                className={styles.JumbotronImage}
                src={imgSrc}
                alt={imgAlt}
                height={imgRadius}
                width={imgRadius}
                style={imgStyle}
            />
            <div>
                {children}
            </div>
        </div>
    </div>
);

Jumbotron.defaultProps = {
    children: [],
    imgStyle: {},
};

Jumbotron.propTypes = {
    children: PropTypes.oneOfType([
        PropTypes.node,
        PropTypes.object,
        PropTypes.array,
    ]),
    imgSrc: PropTypes.string.isRequired,
    imgAlt: PropTypes.string.isRequired,
    imgRadius: PropTypes.number.isRequired,
    imgStyle: PropTypes.object,
};

export default Jumbotron;

import React from 'react';
import PropTypes from 'prop-types';
import styles from './index.scss';

const BackdropInsetShadow = ({ children, className, ...props }) => (
    <div
        {...props}
        className={`${styles.BackdropInsetShadow} ${className}`}
    >
        {children}
    </div>
);

BackdropInsetShadow.defaultProps = {
    children: [],
    className: '',
};

BackdropInsetShadow.propTypes = {
    children: PropTypes.oneOfType([
        PropTypes.node,
        PropTypes.object,
        PropTypes.array,
    ]),
    className: PropTypes.string,
};

export default BackdropInsetShadow;
